ids = await orders_list_order_ids()
futures = [orders_get_order(order_id=i) for i in ids]
orders = [await f for f in futures]
totals = {}
counts = {}
bad = []
for o in orders:
    r = o.get("region")
    a = o.get("amount")
    if r is None or not isinstance(a, (int, float)):
        bad.append(o.get("order_id"))
        continue
    totals[r] = totals.get(r, 0) + a
    counts[r] = counts.get(r, 0) + 1
lines = [f"{r},{round(totals[r], 2):.2f}" for r in sorted(totals)]
return {"n": len(orders), "counts": counts, "bad": bad, "lines": lines, "raw_sum": round(sum(totals.values()), 2)}

